-// Computes C = A * B on the calling thread. C is NOT zeroed by the caller.
-// n is any size from 1 to 2048.
+// Tunable knobs swept by the engine.
+constexpr int M_BLOCK = 64;
+constexpr int J_BLOCK = 64;
+
+#if defined(__ARM_NEON)
+namespace {
+// 4x8 NEON microkernel: adds a_i * B[k, j0..j0+7] into four accumulators
+// (one per row), for k-step. A is a scalar per row; B row is loaded 8-wide.
+inline void micro_4x8(const float* A4, const float* Bp, float* C0, float* C1,
+                      float* C2, float* C3, int n) {
+    float a0 = A4[0], a1 = A4[1], a2 = A4[2], a3 = A4[3];
+    float32x4_t b = vld1q_f32(Bp);
+    float32x4_t acc0 = vld1q_f32(C0);
+    float32x4_t acc1 = vld1q_f32(C1);
+    float32x4_t acc2 = vld1q_f32(C2);
+    float32x4_t acc3 = vld1q_f32(C3);
+    acc0 = vfmaq_f32(acc0, b, vdupq_n_f32(a0));
+    acc1 = vfmaq_f32(acc1, b, vdupq_n_f32(a1));
+    acc2 = vfmaq_f32(acc2, b, vdupq_n_f32(a2));
+    acc3 = vfmaq_f32(acc3, b, vdupq_n_f32(a3));
+    vst1q_f32(C0, acc0);
+    vst1q_f32(C1, acc1);
+    vst1q_f32(C2, acc2);
+    vst1q_f32(C3, acc3);
+}
+} // namespace
+#endif
+
 extern "C" void matmul(int n, const float* A, const float* B, float* C) {
+    // Zero C first.
+    std::fill(C, C + (size_t)n * n, 0.0f);
+
+#if defined(__ARM_NEON)
+    for (int i0 = 0; i0 < n; i0 += M_BLOCK) {
+        int mi = std::min(M_BLOCK, n - i0);
+        for (int j0 = 0; j0 < n; j0 += J_BLOCK) {
+            int mj = std::min(J_BLOCK, n - j0);
+            for (int k = 0; k < n; ++k) {
+                const float* Arow = A + (size_t)(i0 + 0) * n + k;
+                const float* Brow = B + (size_t)k * n + j0;
+                // Process up to 4 rows at a time.
+                int r = 0;
+                for (; r + 3 < mi; r += 4) {
+                    float a0 = A[(size_t)(i0 + r + 0) * n + k];
+                    float a1 = A[(size_t)(i0 + r + 1) * n + k];
+                    float a2 = A[(size_t)(i0 + r + 2) * n + k];
+                    float a3 = A[(size_t)(i0 + r + 3) * n + k];
+                    (void)Arow;
+                    int c = 0;
+                    for (; c + 7 < mj; c += 8) {
+                        float32x4_t b = vld1q_f32(Brow + c);
+                        float32x4_t acc0 = vld1q_f32(C + (size_t)(i0 + r + 0) * n + j0 + c);
+                        float32x4_t acc1 = vld1q_f32(C + (size_t)(i0 + r + 1) * n + j0 + c);
+                        float32x4_t acc2 = vld1q_f32(C + (size_t)(i0 + r + 2) * n + j0 + c);
+                        float32x4_t acc3 = vld1q_f32(C + (size_t)(i0 + r + 3) * n + j0 + c);
+                        acc0 = vfmaq_f32(acc0, b, vdupq_n_f32(a0));
+                        acc1 = vfmaq_f32(acc1, b, vdupq_n_f32(a1));
+                        acc2 = vfmaq_f32(acc2, b, vdupq_n_f32(a2));
+                        acc3 = vfmaq_f32(acc3, b, vdupq_n_f32(a3));
+                        vst1q_f32(C + (size_t)(i0 + r + 0) * n + j0 + c, acc0);
+                        vst1q_f32(C + (size_t)(i0 + r + 1) * n + j0 + c, acc1);
+                        vst1q_f32(C + (size_t)(i0 + r + 2) * n + j0 + c, acc2);
+                        vst1q_f32(C + (size_t)(i0 + r + 3) * n + j0 + c, acc3);
+                    }
+                    // Tail (1..3 columns) scalar.
+                    for (; c < mj; ++c) {
+                        float bv = B[(size_t)k * n + j0 + c];
+                        C[(size_t)(i0 + r + 0) * n + j0 + c] += a0 * bv;
+                        C[(size_t)(i0 + r + 1) * n + j0 + c] += a1 * bv;
+                        C[(size_t)(i0 + r + 2) * n + j0 + c] += a2 * bv;
+                        C[(size_t)(i0 + r + 3) * n + j0 + c] += a3 * bv;
+                    }
+                }
+                // Remaining 1..3 rows scalar.
+                for (; r < mi; ++r) {
+                    float a = A[(size_t)(i0 + r) * n + k];
+                    for (int c = 0; c < mj; ++c)
+                        C[(size_t)(i0 + r) * n + j0 + c] += a * B[(size_t)k * n + j0 + c];
+                }
+            }
+        }
+    }
+#else
     for (int i = 0; i < n; ++i)
